          const r = await lic.ensure();
          if (!r.ok && !trialState().active) return fail(id, S.need_key + ' Get a licence ($' + S.price + ', once): ' + lic.BUY_URL);
          const files = walk(args.dir, args.ext ? [args.ext] : (S.exts || []), []);
